#include "dsp/DropTuner.h"
#include "dsp/SpliceShifter.h"

// Signalsmith Stretch with one extra configure() argument for asymmetric
// windows, generated by CMakeLists.txt from the upstream header.
#include <signalsmith-stretch-asym.h>

#include <array>
#include <cmath>

namespace pedal
{

namespace
{
// Delay of each Signalsmith buffer, in ms (index 0 is the fast engine).
constexpr double stretchDelayMs[DropTuner::numBuffers] = { 0.0, 20.0, 30.0, 40.0, 60.0 };
// With this window asymmetry the delay is (1 - 0.7) = 30% of the window.
constexpr float windowAsymmetry = 0.7f;
} // namespace

struct DropTuner::Impl
{
    SpliceShifter splice;
    // One per Signalsmith buffer, all configured up front so switching never
    // allocates on the audio thread. stretches[i] serves Buffer (i + 1).
    std::array<signalsmith::stretch::SignalsmithStretch<float>, numBuffers - 1> stretches;
    std::array<int, numBuffers> latency {};

    juce::HeapBlock<float> wet, wetNext;
    int maxBlock = 0;
    double sampleRate = 48000.0;
    float currentSemitones = 0.0f, currentTonality = 0.0f;

    // The engine whose output we hear, and the one fading in during a switch.
    int active = 0, next = 0;
    bool running = false, switching = false;

    // Samples left before a freshly reset engine has real output. Fades wait
    // for this so the shifted signal never dips while the engine fills up.
    int startFill = 0, switchFill = 0;

    // 0 = dry, 1 = shifted. Ramped per sample to avoid clicks.
    juce::SmoothedValue<float> mix;
    // 0 = active engine, 1 = next engine.
    juce::SmoothedValue<float> engineBlend;

    void setShift (float semitones, float tonalityHz)
    {
        // Signalsmith takes the tonality limit as a fraction of the sample rate.
        const float limit = tonalityHz > 0.0f ? tonalityHz / (float) sampleRate : 0.0f;
        for (auto& s : stretches)
            s.setTransposeSemitones (semitones, limit);
        splice.setRatio (std::pow (2.0, semitones / 12.0));
    }

    void resetEngine (int engine)
    {
        if (engine == 0)
            splice.reset();
        else
            stretches[(size_t) engine - 1].reset();
    }

    void runEngine (int engine, float* in, float* out, int numSamples)
    {
        if (engine == 0)
        {
            splice.process (in, out, numSamples);
        }
        else
        {
            float* ins[1] = { in };
            float* outs[1] = { out };
            stretches[(size_t) engine - 1].process (ins, numSamples, outs, numSamples);
        }
    }
};

DropTuner::DropTuner() : impl (std::make_unique<Impl>()) {}
DropTuner::~DropTuner() = default;

void DropTuner::prepare (double sampleRate, int maxBlockSize)
{
    impl->sampleRate = sampleRate;
    impl->splice.prepare (sampleRate);
    impl->latency[0] = impl->splice.getTypicalLatencySamples();

    for (int i = 1; i < numBuffers; ++i)
    {
        const double windowSeconds = stretchDelayMs[i] / 1000.0 / (1.0 - windowAsymmetry);
        auto& s = impl->stretches[(size_t) i - 1];
        s.configure (1, (int) (sampleRate * windowSeconds), (int) (sampleRate * windowSeconds / 8.0), false, windowAsymmetry);
        impl->latency[(size_t) i] = s.inputLatency() + s.outputLatency();
    }

    impl->wet.allocate ((size_t) maxBlockSize, true);
    impl->wetNext.allocate ((size_t) maxBlockSize, true);
    impl->maxBlock = maxBlockSize;
    impl->mix.reset (sampleRate, 0.03);
    impl->engineBlend.reset (sampleRate, 0.03);
    reset();
}

void DropTuner::reset()
{
    for (int i = 0; i < numBuffers; ++i)
        impl->resetEngine (i);
    impl->currentSemitones = targetSemitones.load();
    impl->currentTonality = targetTonality.load();
    impl->setShift (impl->currentSemitones, impl->currentTonality);
    impl->active = static_cast<int> (targetBuffer.load());
    impl->switching = false;
    impl->running = targetEnabled.load();
    impl->startFill = impl->switchFill = 0;
    impl->mix.setCurrentAndTargetValue (impl->running ? 1.0f : 0.0f);
    impl->engineBlend.setCurrentAndTargetValue (0.0f);
}

void DropTuner::process (float* samples, int numSamples) noexcept
{
    auto& s = *impl;
    if (numSamples > s.maxBlock)
        return;

    const bool wantOn = targetEnabled.load();
    const float semitones = targetSemitones.load();
    const float tonality = targetTonality.load();
    const int buffer = juce::jlimit (0, numBuffers - 1, static_cast<int> (targetBuffer.load()));

    // While turning off, keep the last shift so the fade-out stays in tune.
    if (wantOn && (! juce::exactlyEqual (semitones, s.currentSemitones) || ! juce::exactlyEqual (tonality, s.currentTonality)))
    {
        s.currentSemitones = semitones;
        s.currentTonality = tonality;
        s.setShift (semitones, tonality);
    }

    if (! s.running)
    {
        s.active = buffer;
        if (! wantOn)
            return;

        s.resetEngine (buffer);
        s.startFill = s.latency[(size_t) buffer];
        s.running = true;
    }
    else if (wantOn && ! s.switching && buffer != s.active)
    {
        s.next = buffer;
        s.resetEngine (buffer);
        s.switchFill = s.latency[(size_t) buffer];
        s.engineBlend.setCurrentAndTargetValue (0.0f);
        s.switching = true;
    }

    s.mix.setTargetValue (wantOn && s.startFill <= 0 ? 1.0f : 0.0f);
    s.startFill -= numSamples;

    if (! wantOn && ! s.mix.isSmoothing() && s.mix.getCurrentValue() <= 0.0f)
    {
        s.running = false;
        s.switching = false;
        return;
    }

    s.runEngine (s.active, samples, s.wet.get(), numSamples);

    if (s.switching)
    {
        s.runEngine (s.next, samples, s.wetNext.get(), numSamples);
        if (s.switchFill <= 0)
            s.engineBlend.setTargetValue (1.0f);
        s.switchFill -= numSamples;

        for (int i = 0; i < numSamples; ++i)
        {
            const float b = s.engineBlend.getNextValue();
            s.wet[i] = s.wet[i] * (1.0f - b) + s.wetNext[i] * b;
        }

        if (! s.engineBlend.isSmoothing() && s.engineBlend.getCurrentValue() >= 1.0f)
        {
            s.active = s.next;
            s.switching = false;
            s.engineBlend.setCurrentAndTargetValue (0.0f);
        }
    }

    for (int i = 0; i < numSamples; ++i)
    {
        const float m = s.mix.getNextValue();
        samples[i] = samples[i] * (1.0f - m) + s.wet[i] * m;
    }
}

int DropTuner::getLatencySamples (Buffer buffer) const noexcept
{
    return impl->latency[(size_t) juce::jlimit (0, numBuffers - 1, static_cast<int> (buffer))];
}

int DropTuner::getLatencySamples() const noexcept
{
    return targetEnabled.load() ? getLatencySamples (targetBuffer.load()) : 0;
}

} // namespace pedal
